import {
  type Msg as LearningMsg,
  LearningPane,
  type State as LearningState,
} from "./learning.ts";
import { samples } from "./samples/index.ts";
import {
  type Anchor,
  anchorText,
  type Mark,
  overlaps,
  type Point,
  type Segment,
  segments,
  type ThreadId,
} from "./selection.ts";
import { type Message, messageText } from "./thread.ts";
import {
  Binder,
  cls,
  mountStyle,
  type Ref,
  ref,
  sanitize,
  show,
  showKeyed,
  type View,
} from "./vamp.ts";

export type State = {
  messages: ReadonlyArray<Message>;
  /** The id of the canned transcript in play, empty for a hand-written one. */
  sample: string;
  inFlight: boolean;
  draft: string;
  /** False at layer 0 (the bare task transcript); true for the two-pane split. */
  split: boolean;
  /** How deep in the tree the left pane is: 0 at layer 0. */
  depth: number;
  /** Whether `→` can move deeper, i.e. there is something to move left. */
  canDescend: boolean;
  /** The thread whose transcript this pane shows; the live selection is over it. */
  thread: ThreadId;
  /** Committed highlights over this transcript. */
  marks: ReadonlyArray<Mark>;
  /** The mark whose thread the right pane is showing, drawn emphasized. */
  activeMark: ThreadId | null;
  anchor: Anchor | null;
  query: string;
  /** How the left pane's thread was opened, absent for the task thread. */
  origin: { action: string; quote: string } | null;
  /** The active child thread, shown on the right when nothing is selected. */
  child: ThreadPaneState | null;
};

export type Msg =
  | { type: "DRAFT_CHANGED"; draft: string }
  | { type: "SUBMIT" }
  | { type: "GO_DEEPER" }
  | { type: "GO_BACK" }
  | { type: "SELECTION_CHANGED"; anchor: Anchor | null }
  | { type: "MARK_CLICKED"; thread: ThreadId }
  | { type: "LEARNING_MSG"; msg: LearningMsg }
  | { type: "SAMPLE_CHANGED"; id: string }
  | { type: "CHILD_MSG"; msg: ThreadPaneMsg };

const appClass = cls("app");
const transcriptClass = cls("transcript");
const messageClass = cls("message");
const roleClass = cls("role");
const composerClass = cls("composer");
const paneClass = cls("pane");
const navClass = cls("nav");
const depthClass = cls("depth");
const markClass = cls("mark");
const textClass = cls("text");
const toolClass = cls("tool");
const toolResultClass = cls("tool-result");
const threadPaneClass = cls("thread-pane");
const threadActionClass = cls("thread-action");
const bodyClass = cls("body");
const originQuoteClass = cls("origin-quote");
const sampleClass = cls("sample");
const spacerClass = cls("spacer");

mountStyle(`
.${appClass} {
  font-family: system-ui, sans-serif;
  height: 100%;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.${bodyClass} {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  width: 100%;
  max-width: 44rem;
  margin: 0 auto;
  padding: 1rem 1rem 5rem;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 1rem 2rem;
  align-items: start;
}
.${appClass}[data-split="true"] .${bodyClass} {
  max-width: 88rem;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}
.${paneClass} {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  min-width: 0;
}
.${navClass} {
  flex: none;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem 1rem;
  border-bottom: 1px solid rgba(0, 0, 0, 0.12);
  background: #fff;
}
.${navClass} button {
  font: inherit;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  border: 1px solid rgba(0, 0, 0, 0.15);
  background: #fff;
  cursor: pointer;
}
.${navClass} button:disabled {
  opacity: 0.4;
  cursor: default;
}
.${sampleClass} {
  font: inherit;
}
.${spacerClass} {
  flex: 1;
}
.${depthClass} {
  font-size: 0.75rem;
  opacity: 0.6;
}
.${markClass} {
  border-radius: 2px;
}
.${markClass}[data-live="true"] {
  background: #cfe3ff;
}
.${markClass}[data-mark] {
  background: #ffe8a3;
  cursor: pointer;
}
.${markClass}[data-mark][data-active="true"] {
  background: #ffcf4d;
  box-shadow: 0 0 0 1px #b8860b;
}
.${transcriptClass} {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.${messageClass} {
  white-space: pre-wrap;
  line-height: 1.5;
}
.${messageClass}[data-role="user"] {
  background: rgba(0, 0, 0, 0.05);
  border-radius: 0.5rem;
  padding: 0.5rem 0.75rem;
}
.${toolClass} {
  font-family: ui-monospace, monospace;
  font-size: 0.8rem;
  border: 1px solid rgba(0, 0, 0, 0.15);
  border-radius: 0.4rem;
  padding: 0.4rem 0.6rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  overflow-x: auto;
}
.${toolClass} pre {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
}
.${toolResultClass}[data-status="error"] {
  color: #b00020;
}
.${roleClass} {
  display: block;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.6;
}
.${composerClass} {
  display: flex;
  gap: 0.5rem;
}
.${threadPaneClass} {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  border-left: 1px solid rgba(0, 0, 0, 0.1);
  padding-left: 1.5rem;
}
.${originQuoteClass} {
  white-space: pre-wrap;
  border-left: 3px solid #f0b429;
  margin: 0.4rem 0 0;
  padding-left: 0.75rem;
  max-height: 8rem;
  overflow-y: auto;
  font-size: 0.9rem;
  opacity: 0.8;
}
.${threadActionClass} {
  white-space: pre-wrap;
  font-weight: 600;
  font-size: 0.95rem;
}
.${composerClass} textarea {
  flex: 1;
  font: inherit;
  padding: 0.5rem;
  resize: vertical;
}
`);

type SegmentState = {
  text: string;
  /** The thread this run opens; null for plain text and the live selection. */
  thread: ThreadId | null;
  live: boolean;
  active: boolean;
};

type SegmentMsg = { type: "CLICKED"; thread: ThreadId };

/** One run of a message's text: plain, a committed mark, or the live selection.
 * A span rather than a <mark> so all three share one element and bindList can
 * reconcile them without remounting. */
class SegmentView implements View<SegmentState, SegmentMsg> {
  container: HTMLElement;
  private b: Binder<SegmentState>;
  private current: SegmentState;

  constructor(
    container: HTMLElement,
    dispatch: (msg: SegmentMsg) => void,
    initial: SegmentState,
  ) {
    const textRef = ref("segment");
    container.innerHTML = sanitize`<span data-ref="${textRef}"></span>`;
    this.container = container;
    this.current = initial;
    this.b = new Binder(container, initial);
    container.addEventListener("click", () => {
      const thread = this.current.thread;
      if (thread) dispatch({ type: "CLICKED", thread });
    });
    this.b.bindClass(container, (s) => (s.thread || s.live ? markClass : ""));
    this.b.bindContainerAttr("data-mark", (s) => s.thread ?? undefined);
    this.b.bindContainerAttr("data-live", (s) => (s.live ? "true" : undefined));
    this.b.bindContainerAttr("data-active", (s) =>
      s.active ? "true" : undefined,
    );
    this.b.bindText(textRef, (s) => s.text);
  }

  sync(state: SegmentState): void {
    this.current = state;
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

type MessageState = {
  message: Message;
  segments: ReadonlyArray<Segment>;
  active: ThreadId | null;
};

class MessageView implements View<MessageState, SegmentMsg> {
  container: HTMLElement;
  private b: Binder<MessageState>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: SegmentMsg) => void,
    initial: MessageState,
  ) {
    const roleRef = ref("role");
    const textRef = ref("text");
    const toolRef = ref("tool");
    const toolNameRef = ref("tool-name");
    const toolInputRef = ref("tool-input");
    const toolResultRef = ref("tool-result");
    container.className = messageClass;
    // The tool block sits outside the .text span on purpose: resolvePoint only
    // anchors inside it, so a tool call is rendered but not selectable.
    container.innerHTML = sanitize`
      <span class="${roleClass}" data-ref="${roleRef}"></span>
      <span class="${textClass}" data-ref="${textRef}"></span>
      <div class="${toolClass}" data-tool data-ref="${toolRef}">
        <strong data-tool-name data-ref="${toolNameRef}"></strong>
        <pre data-tool-input data-ref="${toolInputRef}"></pre>
        <pre class="${toolResultClass}" data-tool-result data-ref="${toolResultRef}"></pre>
      </div>
    `;
    this.container = container;
    this.b = new Binder(container, initial);
    this.b.bindText(roleRef, (s) => s.message.role);
    // Keyed by start offset: the transcript is append-only, so a run keeps its
    // start while the message grows and while marks are added after it.
    this.b.bindList(textRef, "span", (s) =>
      s.segments.map((seg) =>
        showKeyed(
          String(seg.start),
          SegmentView,
          {
            text: messageText(s.message).slice(seg.start, seg.end),
            thread: seg.thread,
            live: seg.live,
            active: seg.thread !== null && seg.thread === s.active,
          },
          {},
          dispatch,
        ),
      ),
    );
    this.b.bindVisible(toolRef, (s) => s.message.type === "tool_use");
    this.b.bindText(toolNameRef, (s) =>
      s.message.type === "tool_use" ? s.message.call.name : "",
    );
    this.b.bindText(toolInputRef, (s) =>
      s.message.type === "tool_use" ? s.message.call.inputJson : "",
    );
    this.b.bindText(toolResultRef, (s) => resultText(s.message));
    this.b.bindVisible(toolResultRef, (s) => resultText(s.message) !== "");
    this.b.bindAttr(toolResultRef, "data-status", (s) =>
      s.message.type === "tool_use" ? s.message.call.result?.status : undefined,
    );
    this.b.bindContainerAttr("data-role", (s) => s.message.role);
  }

  sync(state: MessageState): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

function resultText(message: Message): string {
  if (message.type !== "tool_use") return "";
  const result = message.call.result;
  if (!result) return "";
  return result.status === "ok" ? result.text : result.error;
}

export type ThreadPaneState = {
  /** What the user asked for when they opened this thread. */
  action: string;
  messages: ReadonlyArray<Message>;
  inFlight: boolean;
  draft: string;
};

export type ThreadPaneMsg =
  | { type: "DRAFT_CHANGED"; draft: string }
  | { type: "SUBMIT" };

/** A learning thread on the right: the passage it came from, its transcript,
 * and a composer. Read-only as far as selection goes - only the left pane
 * captures one. */
class ThreadPane implements View<ThreadPaneState, ThreadPaneMsg> {
  container: HTMLElement;
  private b: Binder<ThreadPaneState>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: ThreadPaneMsg) => void,
    initial: ThreadPaneState,
  ) {
    const actionRef = ref("thread-action");
    const transcriptRef = ref("thread-transcript");
    const inputRef = ref("thread-input");
    const sendRef = ref("thread-send");

    container.className = threadPaneClass;
    container.innerHTML = sanitize`
      <div class="${threadActionClass}" data-thread-action data-ref="${actionRef}"></div>
      <ul class="${transcriptClass}" data-ref="${transcriptRef}"></ul>
      <div class="${composerClass}">
        <textarea data-ref="${inputRef}" rows="2" placeholder="Follow up…"></textarea>
        <button type="button" data-ref="${sendRef}">Reply</button>
      </div>
    `;
    this.container = container;
    this.b = new Binder(container, initial);

    const input = this.b.ref<HTMLTextAreaElement>(inputRef);
    input.addEventListener("input", () => {
      dispatch({ type: "DRAFT_CHANGED", draft: input.value });
    });
    input.addEventListener("keydown", (e: KeyboardEvent) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        dispatch({ type: "SUBMIT" });
      }
    });
    this.b
      .ref(sendRef)
      .addEventListener("click", () => dispatch({ type: "SUBMIT" }));

    this.b.bindText(actionRef, (s) => s.action);
    this.b.bindList(transcriptRef, "li", (s) =>
      s.messages.map((message, i) =>
        showKeyed(
          String(i),
          MessageView,
          {
            message,
            segments: segments([], null, i, messageText(message).length),
            active: null,
          },
          {},
          () => {},
        ),
      ),
    );
    this.b.bindValue(inputRef, (s) => s.draft);
    this.b.bindDisabled(inputRef, (s) => s.inFlight);
    this.b.bindDisabled(sendRef, (s) => s.inFlight || s.draft.trim() === "");
  }

  sync(state: ThreadPaneState): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

export class AppView implements View<State, Msg> {
  container: HTMLElement;
  private b: Binder<State>;
  /** The latest state, for event handlers that need it outside a binding. */
  private current: State;

  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initialState: State,
  ) {
    const transcriptRef: Ref = ref("transcript");
    const inputRef: Ref = ref("input");
    const sendRef: Ref = ref("send");
    const backRef: Ref = ref("back");
    const forwardRef: Ref = ref("forward");
    const depthRef: Ref = ref("depth");
    const composerRef: Ref = ref("composer");
    const learningRef: Ref = ref("learning");
    const originRef: Ref = ref("origin");
    const originActionRef: Ref = ref("origin-action");
    const originQuoteRef: Ref = ref("origin-quote");
    const sampleRef: Ref = ref("sample");

    container.className = appClass;
    container.innerHTML = sanitize`
      <div class="${navClass}">
        <select class="${sampleClass}" data-ref="${sampleRef}"></select>
        <span class="${spacerClass}"></span>
        <button type="button" data-ref="${backRef}">← Back</button>
        <span class="${depthClass}" data-ref="${depthRef}"></span>
        <button type="button" data-ref="${forwardRef}"></button>
      </div>
      <div class="${bodyClass}">
      <div class="${paneClass}">
        <div data-ref="${originRef}">
          <div class="${threadActionClass}" data-focus-action data-ref="${originActionRef}"></div>
          <blockquote class="${originQuoteClass}" data-focus-quote data-ref="${originQuoteRef}"></blockquote>
        </div>
        <ul class="${transcriptClass}" data-ref="${transcriptRef}"></ul>
        <div class="${composerClass}" data-ref="${composerRef}">
          <textarea data-ref="${inputRef}" rows="2" placeholder="Ask something…"></textarea>
          <button type="button" data-ref="${sendRef}">Send</button>
        </div>
      </div>
        <div data-ref="${learningRef}"></div>
      </div>
    `;
    this.container = container;
    this.current = initialState;
    this.b = new Binder(container, initialState);

    const input = this.b.ref<HTMLTextAreaElement>(inputRef);
    input.addEventListener("input", () => {
      dispatch({ type: "DRAFT_CHANGED", draft: input.value });
    });
    input.addEventListener("keydown", (e: KeyboardEvent) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        dispatch({ type: "SUBMIT" });
      }
    });
    this.b
      .ref(sendRef)
      .addEventListener("click", () => dispatch({ type: "SUBMIT" }));
    // The option list is a module constant, so it is built once rather than
    // bound; switching sample is a page navigation anyway.
    const picker = this.b.ref<HTMLSelectElement>(sampleRef);
    const own = document.createElement("option");
    own.value = "";
    own.textContent = "Write your own";
    picker.append(own);
    for (const sample of samples) {
      const option = document.createElement("option");
      option.value = sample.id;
      option.textContent = sample.label;
      picker.append(option);
    }
    picker.addEventListener("change", () => {
      dispatch({ type: "SAMPLE_CHANGED", id: picker.value });
    });

    this.b
      .ref(backRef)
      .addEventListener("click", () => dispatch({ type: "GO_BACK" }));
    this.b
      .ref(forwardRef)
      .addEventListener("click", () => dispatch({ type: "GO_DEEPER" }));

    // Capture on mouseup/keyup rather than `selectionchange`: the browser
    // collapses the selection as soon as the user clicks the learning pane,
    // which is exactly when we need the anchor to survive.
    const transcript = this.b.ref(transcriptRef);
    const capture = () => {
      const anchor = readAnchor(transcript, this.current.thread);
      if (anchor !== undefined) dispatch({ type: "SELECTION_CHANGED", anchor });
    };
    transcript.addEventListener("mouseup", capture);
    transcript.addEventListener("keyup", capture);

    // The transcript is append-only and never reorders, so the position of a
    // message is a stable identity.
    this.b.bindList(transcriptRef, "li", (s) =>
      s.messages.map((message, i) =>
        showKeyed(
          String(i),
          MessageView,
          {
            message,
            segments: segments(
              s.marks,
              s.anchor,
              i,
              messageText(message).length,
            ),
            active: s.activeMark,
          },
          {},
          (msg: SegmentMsg) =>
            dispatch({ type: "MARK_CLICKED", thread: msg.thread }),
        ),
      ),
    );
    this.b.bindValue(sampleRef, (s) => s.sample);
    this.b.bindContainerAttr("data-split", (s) => (s.split ? "true" : "false"));
    this.b.bindText(forwardRef, (s) => `${descendLabel(s.depth + 1)} →`);
    this.b.bindDisabled(forwardRef, (s) => s.split && !s.canDescend);
    // Not rendered at layer 0: there is nowhere above the task thread.
    this.b.bindVisible(backRef, (s) => s.split);
    this.b.bindText(depthRef, (s) => `Layer ${s.depth}`);
    this.b.bindVisible(originRef, (s) => s.origin !== null);
    this.b.bindText(originActionRef, (s) => s.origin?.action ?? "");
    this.b.bindText(originQuoteRef, (s) => s.origin?.quote ?? "");
    this.b.bindSlot(learningRef, (s) => {
      if (!s.split) return undefined;
      const child = s.child;
      // A live selection and an active child compete for this pane; the newer
      // one wins, and a selection is always the newer of the two here because
      // opening or clicking a thread clears it.
      if (child && !s.anchor) {
        return show(ThreadPane, child, {}, (msg: ThreadPaneMsg) =>
          dispatch({ type: "CHILD_MSG", msg }),
        );
      }
      const learningState: LearningState = {
        selection: paneSelection(s),
        overlapping: s.anchor !== null && overlaps(s.marks, s.anchor),
        query: s.query,
      };
      // bindSlot hands this straight to the child as its dispatch, so it must
      // dispatch rather than return a wrapped message.
      return show(LearningPane, learningState, {}, (msg: LearningMsg) =>
        dispatch({ type: "LEARNING_MSG", msg }),
      );
    });
    this.b.bindValue(inputRef, (s) => s.draft);
    this.b.bindDisabled(inputRef, (s) => s.inFlight);
    this.b.bindDisabled(sendRef, (s) => s.inFlight || s.draft.trim() === "");
  }

  sync(state: State): void {
    this.current = state;
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

/** Names the layer `→` leads to. */
function descendLabel(destination: number): string {
  switch (destination) {
    case 1:
      return "Reflect";
    case 3:
      return "We must go deeper";
    case 4:
      return "Thinkception!";
    default:
      return "Go deeper";
  }
}

/** The passage the right pane is about: the live selection, or - once one has
 * been committed - the mark whose thread is active. */
function paneSelection(s: State): string | null {
  if (s.anchor) return anchorText(s.anchor, s.messages);
  const active = s.marks.find((m) => m.thread === s.activeMark);
  return active ? anchorText(active.anchor, s.messages) : null;
}
/** Reads the live browser selection as an Anchor. Returns `undefined` when the
 * selection has nothing to do with the transcript, which must not clobber a
 * previously captured anchor. */
function readAnchor(
  transcript: HTMLElement,
  thread: ThreadId,
): Anchor | null | undefined {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return undefined;
  const range = selection.getRangeAt(0);
  const start = resolvePoint(
    transcript,
    range.startContainer,
    range.startOffset,
  );
  const end = resolvePoint(transcript, range.endContainer, range.endOffset);
  if (!start || !end) return undefined;
  if (start.msg === end.msg && start.offset === end.offset) return null;
  return { thread, start, end };
}

function resolvePoint(
  transcript: HTMLElement,
  node: Node,
  offset: number,
): Point | null {
  const el =
    node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element);
  const textEl = el?.closest(`.${textClass}`);
  if (!textEl || !transcript.contains(textEl)) return null;
  const li = textEl.closest("li");
  if (!li) return null;
  const msg = Array.prototype.indexOf.call(transcript.children, li);
  if (msg < 0) return null;

  // The message text is split across pre/mark/post spans, so a node-local
  // offset is not a message offset; measure the text preceding the point.
  const prefix = document.createRange();
  prefix.setStart(textEl, 0);
  prefix.setEnd(node, offset);
  return { msg, offset: prefix.toString().length };
}

import type { Action } from "./prompt.ts";
import { Binder, cls, mountStyle, ref, sanitize, type View } from "./vamp.ts";

export type { Action };

export type State = {
  /** The text the user highlighted, or null when nothing is selected. */
  selection: string | null;
  /** The live selection intersects a committed mark, so no action is offered. */
  overlapping: boolean;
  query: string;
};

export type Msg =
  | { type: "ACTION"; action: Action }
  | { type: "QUERY_CHANGED"; query: string };

const paneClass = cls("learning-pane");
const emptyClass = cls("learning-empty");
const quoteClass = cls("learning-quote");
const actionsClass = cls("learning-actions");
const warnClass = cls("learning-warn");

mountStyle(`
.${paneClass} {
  position: sticky;
  top: 4rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  border-left: 1px solid rgba(0, 0, 0, 0.1);
  padding-left: 1.5rem;
}
.${emptyClass} {
  opacity: 0.5;
  font-style: italic;
}
.${warnClass} {
  font-style: italic;
  color: #a35200;
}
.${quoteClass} {
  white-space: pre-wrap;
  border-left: 3px solid #f0b429;
  padding-left: 0.75rem;
  max-height: 12rem;
  overflow-y: auto;
  font-size: 0.9rem;
}
.${actionsClass} {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0.5rem;
}
.${actionsClass} button {
  font: inherit;
  text-align: left;
  padding: 0.5rem 0.75rem;
}
.${actionsClass} textarea {
  font: inherit;
  padding: 0.5rem;
  resize: vertical;
}
`);

export class LearningPane implements View<State, Msg> {
  container: HTMLElement;
  private b: Binder<State>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initialState: State,
  ) {
    const emptyRef = ref("empty");
    const bodyRef = ref("body");
    const quoteRef = ref("quote");
    const explainRef = ref("explain");
    const quizRef = ref("quiz");
    const queryRef = ref("query");
    const warnRef = ref("warn");

    container.className = paneClass;
    container.innerHTML = sanitize`
      <p class="${emptyClass}" data-ref="${emptyRef}">Select some text to get started.</p>
      <p class="${warnClass}" data-ref="${warnRef}">Select a non-overlapping section.</p>
      <div class="${actionsClass}" data-ref="${bodyRef}">
        <blockquote class="${quoteClass}" data-ref="${quoteRef}"></blockquote>
        <button type="button" data-ref="${explainRef}">I don't understand this.</button>
        <button type="button" data-ref="${quizRef}">Quiz me on this.</button>
        <textarea data-ref="${queryRef}" rows="2" placeholder="Ask your own question…"></textarea>
      </div>
    `;
    this.container = container;
    this.b = new Binder(container, initialState);

    this.b
      .ref(explainRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "explain" } }),
      );
    this.b
      .ref(quizRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "quiz" } }),
      );

    const query = this.b.ref<HTMLTextAreaElement>(queryRef);
    query.addEventListener("input", () => {
      dispatch({ type: "QUERY_CHANGED", query: query.value });
    });
    query.addEventListener("keydown", (e: KeyboardEvent) => {
      if (e.key !== "Enter" || e.shiftKey) return;
      e.preventDefault();
      const text = query.value.trim();
      if (text === "") return;
      dispatch({ type: "ACTION", action: { type: "query", text } });
    });

    this.b.bindVisible(emptyRef, (s) => s.selection === null && !s.overlapping);
    this.b.bindVisible(warnRef, (s) => s.overlapping);
    this.b.bindVisible(bodyRef, (s) => s.selection !== null && !s.overlapping);
    this.b.bindText(quoteRef, (s) => s.selection ?? "");
    this.b.bindValue(queryRef, (s) => s.query);
  }

  sync(state: State): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

/** One id space over nodes and edges, so `get` takes a single list. */
export type GraphId = NodeId | EdgeId;
/** Minted by the graph (`n0`, `n1`, ...). Opaque; never derived from the title. */
export type NodeId = string & { readonly __brand: "NodeId" };
/** Minted by the graph (`e0`, `e1`, ...). */
export type EdgeId = string & { readonly __brand: "EdgeId" };

/** The agent's estimate, not a measurement. A misconception can look fluent,
 * so it belongs in `notes`, not here. */
export type Level = 1 | 2 | 3 | 4;
export const LEVELS = ["unfamiliar", "emerging", "working", "fluent"] as const;

export const levelLabel = (level: Level) => `${level} ${LEVELS[level - 1]}`;

export type GraphNode = {
  id: NodeId;
  /** Unique among nodes and non-empty, up to ~5 words. A label, not the key. */
  title: string;
  /** What the domain knowledge itself is. */
  description: string;
  /** The agent's read on this user's grasp of it, including misconceptions. */
  notes: string;
  level: Level;
};

export type GraphEdge = {
  id: EdgeId;
  from: NodeId;
  to: NodeId;
  /** 1-2 words. Several edges may join the same pair. */
  title: string;
  description: string;
};

export type GraphResult =
  | { status: "ok"; message: string }
  | { status: "error"; error: string };

export const isNodeId = (id: string): id is NodeId => id.startsWith("n");
export const isEdgeId = (id: string): id is EdgeId => id.startsWith("e");

export class KnowledgeGraph {
  #nodes = new Map<NodeId, GraphNode>();
  #edges = new Map<EdgeId, GraphEdge>();
  #next = 0;

  get nodes(): ReadonlyArray<GraphNode> {
    return [...this.#nodes.values()];
  }

  get edges(): ReadonlyArray<GraphEdge> {
    return [...this.#edges.values()];
  }

  node(id: NodeId): GraphNode | undefined {
    return this.#nodes.get(id);
  }

  edge(id: EdgeId): GraphEdge | undefined {
    return this.#edges.get(id);
  }

  /** Creates with a fresh id when `id` is omitted, updates in place when it is
   * given. Rejects an unknown id, an empty title, or a title already used by
   * another node. */
  putNode(node: Omit<GraphNode, "id"> & { id?: NodeId }): GraphResult {
    const title = node.title.trim();
    if (title === "") return { status: "error", error: "node title is empty" };
    if (node.id !== undefined && !this.#nodes.has(node.id))
      return { status: "error", error: `no node with id ${node.id}` };
    for (const other of this.#nodes.values())
      if (other.title === title && other.id !== node.id)
        return {
          status: "error",
          error: `title "${title}" is already used by node ${other.id}`,
        };
    const id = node.id ?? (`n${this.#next++}` as NodeId);
    this.#nodes.set(id, {
      id,
      title,
      description: node.description,
      notes: node.notes,
      level: node.level,
    });
    return {
      status: "ok",
      message: `${node.id === undefined ? "created" : "updated"} node ${id} "${title}"`,
    };
  }

  /** Cascades to incident edges. */
  deleteNode(id: NodeId): GraphResult {
    const node = this.#nodes.get(id);
    if (!node) return { status: "error", error: `no node with id ${id}` };
    let removed = 0;
    for (const edge of [...this.#edges.values()])
      if (edge.from === id || edge.to === id) {
        this.#edges.delete(edge.id);
        removed++;
      }
    this.#nodes.delete(id);
    return {
      status: "ok",
      message: `deleted node ${id} "${node.title}" and ${removed} incident edge(s)`,
    };
  }

  /** Errors if either endpoint is unknown. */
  putEdge(edge: Omit<GraphEdge, "id"> & { id?: EdgeId }): GraphResult {
    const title = edge.title.trim();
    if (title === "") return { status: "error", error: "edge title is empty" };
    if (edge.id !== undefined && !this.#edges.has(edge.id))
      return { status: "error", error: `no edge with id ${edge.id}` };
    if (!this.#nodes.has(edge.from))
      return { status: "error", error: `no node with id ${edge.from}` };
    if (!this.#nodes.has(edge.to))
      return { status: "error", error: `no node with id ${edge.to}` };
    if (edge.from === edge.to)
      return {
        status: "error",
        error: "an edge may not join a node to itself",
      };
    const id = edge.id ?? (`e${this.#next++}` as EdgeId);
    this.#edges.set(id, {
      id,
      from: edge.from,
      to: edge.to,
      title,
      description: edge.description,
    });
    return {
      status: "ok",
      message: `${edge.id === undefined ? "created" : "updated"} edge ${id} "${title}" (${edge.from} -> ${edge.to})`,
    };
  }

  deleteEdge(id: EdgeId): GraphResult {
    const edge = this.#edges.get(id);
    if (!edge) return { status: "error", error: `no edge with id ${id}` };
    this.#edges.delete(id);
    return { status: "ok", message: `deleted edge ${id} "${edge.title}"` };
  }

  /** Everything about each id: a node with its incident edges in both
   * directions, or an edge with its endpoints. Unknown ids come back marked
   * as such rather than failing the batch. */
  get(ids: ReadonlyArray<GraphId>): string {
    return ids.map((id) => this.#record(id)).join("\n\n");
  }

  #record(id: GraphId): string {
    const node = this.#nodes.get(id as NodeId);
    if (node) {
      const incident = this.edges.filter(
        (e) => e.from === node.id || e.to === node.id,
      );
      return [
        `node ${node.id} "${node.title}" level ${levelLabel(node.level)}`,
        `description: ${node.description}`,
        `notes: ${node.notes}`,
        incident.length === 0
          ? "edges: (none)"
          : [
              "edges:",
              ...incident.map(
                (e) =>
                  `  ${e.id} "${e.title}" ${this.#label(e.from)} -> ${this.#label(e.to)}`,
              ),
            ].join("\n"),
      ].join("\n");
    }
    const edge = this.#edges.get(id as EdgeId);
    if (edge)
      return [
        `edge ${edge.id} "${edge.title}" ${this.#label(edge.from)} -> ${this.#label(edge.to)}`,
        `description: ${edge.description}`,
      ].join("\n");
    return `${id}: not found`;
  }

  #label(id: NodeId): string {
    const node = this.#nodes.get(id);
    return node ? `${id} "${node.title}"` : `${id} (missing)`;
  }

  /** The overview - one line per node and edge, id and title and level -
   * injected into the seed of any thread that needs it. An empty graph renders
   * as a line saying so, not as "". */
  render(): string {
    if (this.#nodes.size === 0 && this.#edges.size === 0)
      return "The knowledge graph is empty: it has no nodes and no edges yet.";
    return [
      "nodes:",
      ...this.nodes.map(
        (n) => `  ${n.id} "${n.title}" - ${levelLabel(n.level)}`,
      ),
      "edges:",
      ...(this.#edges.size === 0
        ? ["  (none)"]
        : this.edges.map((e) => `  ${e.id} "${e.title}" ${e.from} -> ${e.to}`)),
    ].join("\n");
  }
}

import type { KnowledgeGraph, NodeId } from "./graph.ts";

export type Position = { x: number; y: number };

type Body = { id: NodeId; x: number; y: number; dx: number; dy: number };

const ITERATIONS = 300;
/** The side of the square the simulation runs in before normalization. */
const SIDE = 1;

/** Deterministic: same graph in, same positions out. Coordinates are
 * normalized to [0, 1] so the view scales them to the canvas. */
export function layout(graph: KnowledgeGraph): Map<NodeId, Position> {
  const ids = graph.nodes.map((n) => n.id).sort();
  if (ids.length === 0) return new Map();
  if (ids.length === 1)
    return new Map(ids.map((id) => [id, { x: 0.5, y: 0.5 }]));

  // Initial placement on a circle in id order: no Math.random, so the whole
  // simulation is a pure function of the graph.
  const bodies: Body[] = ids.map((id, i) => {
    const angle = (2 * Math.PI * i) / ids.length;
    return {
      id,
      x: SIDE / 2 + (SIDE / 2) * Math.cos(angle),
      y: SIDE / 2 + (SIDE / 2) * Math.sin(angle),
      dx: 0,
      dy: 0,
    };
  });
  const byId = new Map(bodies.map((b) => [b.id, b]));
  const edges = graph.edges.flatMap((e) => {
    const from = byId.get(e.from);
    const to = byId.get(e.to);
    return from && to ? [[from, to] as const] : [];
  });
  const k = Math.sqrt((SIDE * SIDE) / bodies.length);

  for (let step = 0; step < ITERATIONS; step++) {
    const temperature = (SIDE / 10) * (1 - step / ITERATIONS);
    for (const body of bodies) {
      body.dx = 0;
      body.dy = 0;
    }

    bodies.forEach((a, i) => {
      for (const b of bodies.slice(i + 1)) {
        const { ux, uy, dist } = unit(a, b, i);
        const force = (k * k) / dist;
        a.dx += ux * force;
        a.dy += uy * force;
        b.dx -= ux * force;
        b.dy -= uy * force;
      }
    });

    for (const [from, to] of edges) {
      const { ux, uy, dist } = unit(from, to, 0);
      const force = (dist * dist) / k;
      from.dx -= ux * force;
      from.dy -= uy * force;
      to.dx += ux * force;
      to.dy += uy * force;
    }

    for (const body of bodies) {
      const len = Math.hypot(body.dx, body.dy) || 1;
      const scale = Math.min(len, temperature) / len;
      body.x += body.dx * scale;
      body.y += body.dy * scale;
    }
  }

  return normalize(bodies);
}

/** Unit vector from `b` towards `a`, with a deterministic nudge when the two
 * land exactly on top of each other. */
function unit(
  a: Body,
  b: Body,
  seed: number,
): { ux: number; uy: number; dist: number } {
  let dx = a.x - b.x;
  let dy = a.y - b.y;
  let dist = Math.hypot(dx, dy);
  if (dist < 1e-6) {
    dx = 1e-4 * (seed + 1);
    dy = 1e-4;
    dist = Math.hypot(dx, dy);
  }
  return { ux: dx / dist, uy: dy / dist, dist };
}

/** Fit to [0, 1] on both axes independently; a degenerate axis collapses to
 * the middle rather than dividing by zero. */
function normalize(bodies: ReadonlyArray<Body>): Map<NodeId, Position> {
  const span = (values: number[]) => {
    const lo = Math.min(...values);
    const hi = Math.max(...values);
    return (v: number) => (hi - lo < 1e-9 ? 0.5 : (v - lo) / (hi - lo));
  };
  const fitX = span(bodies.map((b) => b.x));
  const fitY = span(bodies.map((b) => b.y));
  return new Map(bodies.map((b) => [b.id, { x: fitX(b.x), y: fitY(b.y) }]));
}

